// Package: Azure.ResourceManager.Sql
// Install: dotnet add package Azure.ResourceManager.Sql

using Azure.Identity;
using Azure.ResourceManager;
using Azure.ResourceManager.Sql;
using Azure.ResourceManager.Sql.Models;

public class AzureSqlProvisioningService
{
    private readonly ArmClient _armClient;

    public AzureSqlProvisioningService()
    {
        _armClient = new ArmClient(new DefaultAzureCredential());
    }

    public async Task ProvisionAsync(string resourceGroupName, string serverName, string databaseName, CancellationToken ct = default)
    {
        try
        {
            var subscription = await _armClient.GetDefaultSubscriptionAsync(ct);
            var rgResponse = await subscription.GetResourceGroups()
                .GetAsync(resourceGroupName, ct);
            var resourceGroup = rgResponse.Value;

            // Create SQL server with Azure AD authentication
            var serverData = new SqlServerData(AzureLocation.EastUS)
            {
                Administrators = new ServerExternalAdministratorProperties
                {
                    AdministratorType = ServerExternalAdministratorType.ActiveDirectory,
                    Login = "azure-admin",
                    Sid = Guid.Parse("your-guid-here"),
                    TenantId = Guid.Parse("your-tenant-guid-here"),
                    AzureADOnlyAuthentication = true
                }
            };

            var serverLro = await resourceGroup.GetSqlServers()
                .CreateOrUpdateAsync(WaitUntil.Completed, serverName, serverData, ct);
            var server = serverLro.Value;
            Console.WriteLine($"Server '{server.Data.Name}' provisioned in {server.Data.Location}");

            // Create database with serverless General Purpose SKU
            var dbData = new SqlDatabaseData(AzureLocation.EastUS)
            {
                Sku = new SqlSku("GP_S_Gen5_2")
            };

            var dbLro = await server.GetSqlDatabases()
                .CreateOrUpdateAsync(WaitUntil.Completed, databaseName, dbData, ct);
            var database = dbLro.Value;
            Console.WriteLine($"Database '{database.Data.Name}' created (sku: {database.Data.Sku.Name})");
        }
        catch (RequestFailedException ex)
        {
            Console.WriteLine($"Provisioning failed: {ex.Status} - {ex.Message}");
            throw;
        }
    }
}

// Usage
var provisioning = new AzureSqlProvisioningService();
await provisioning.ProvisionAsync("azure-for-aspnet-rg", "aspnet-sql-server-001", "BlogDb");

// Expected output:
// Server 'aspnet-sql-server-001' provisioned in eastus
// Database 'BlogDb' created (sku: GP_S_Gen5_2)

// Package: Azure.ResourceManager.Sql
// Install: dotnet add package Azure.ResourceManager.Sql

using Azure.ResourceManager.Sql;
using Azure.ResourceManager.Sql.Models;

public class AzureSqlNetworkService
{
    private readonly SqlServerResource _server;

    public AzureSqlNetworkService(SqlServerResource server) => _server = server;

    public async Task AllowAzureServicesAsync(CancellationToken ct = default)
    {
        try
        {
            var firewallRule = await _server.GetSqlFirewallRules()
                .CreateOrUpdateAsync(
                    WaitUntil.Completed,
                    "AllowAzureServices",
                    new SqlFirewallRuleData
                    {
                        StartIpAddress = "0.0.0.0",
                        EndIpAddress = "0.0.0.0"
                    },
                    ct);

            Console.WriteLine($"Firewall rule '{firewallRule.Value.Data.Name}' created - Azure services can connect");
        }
        catch (RequestFailedException ex)
        {
            Console.WriteLine($"Firewall rule creation failed: {ex.Message}");
            throw;
        }
    }
}

// Usage - allow all Azure services to reach the SQL server
var networkService = new AzureSqlNetworkService(server);
await networkService.AllowAzureServicesAsync();

// Expected output:
// Firewall rule 'AllowAzureServices' created - Azure services can connect
